package install

import (
	"context"
	"crypto/ed25519"
	"fmt"
	"time"

	a "clawreef/internal/systembackupkekadapter"
	reg "clawreef/internal/systembackupkekregistry"
)

// Record identities are generated by this owner from the original operation
// and exact material identity. There is no caller-selected source/record/hash.
func (b *issuedOriginalMixedAdoptionControls) controlSource(partition reg.Partition, kind string) reg.SourceRecord {
	id := originalObjectSHA(struct{ Operation, Material, Partition, Kind string }{b.hold.set.owner.operation, b.material.SHA256, string(partition), kind})
	return reg.SourceRecord{SourceID: "original-owner:" + id, RecordID: fmt.Sprintf("sev_%s-%s-%s-%s-%s", id[:8], id[8:12], id[12:16], id[16:20], id[20:32]), RecordVersion: "original-adoption.v1"}
}

func (b *issuedOriginalMixedAdoptionControls) recordRevision() string {
	return originalObjectSHA(struct{ Operation, SQL, Snapshot, Fence, Material string }{b.hold.set.owner.operation, b.coverage.history.finite.metadata.revision, b.coverage.history.snapshotRevision, b.coverage.history.fenceRevision, b.material.SHA256})
}

// These are private owner projections of genuine held sources. Do not marshal
// private source structs: that would silently sign an empty JSON object.
func (b *issuedOriginalMixedAdoptionControls) actualOwnerObservation(kind string) (any, error) {
	s := b.coverage.history
	if !s.local(b.ctx, false) {
		return nil, ErrInstall
	}
	switch kind {
	case "immutable_external_snapshot":
		return struct {
			Version, SQL, Consumers, Snapshot, Business string
			Protected                                   any
			Warm, Cold                                  originalMinIOExactInventoryCommitment
			Retained                                    any
			Classes                                     []originalMinIOHistoryObjectClass
		}{"original-protected-native-mixed-history.v1", s.finite.metadata.revision, s.finite.resolved.revision, s.snapshotRevision, s.business.revision, s.external.warm.facts, originalMinIOInventoryCommitment(s.external.warm.warm, s.external.warm.warmEvidence), originalMinIOInventoryCommitment(s.external.cold, s.external.afterEvidence), s.external.archive.retained.data, retainedC1Copy(s.objectClasses)}, nil
	case "original_writer_fence":
		return struct {
			Version, Operation, Inventory, Native, Fence string
			Reservation                                  any
			Until                                        time.Time
		}{"original-mixed-held-writer-fence.v1", b.hold.set.owner.operation, b.hold.set.inventorySHA, s.finite.originalNative.digest, s.fenceRevision, b.prep.reservation, s.finite.nativeUntil}, nil
	case "historical_backfill":
		refs := s.references()
		if len(refs) == 0 || len(b.snapshot.References) != 0 || !reg.SameSnapshotFacts(b.snapshot, s.retained.before) {
			return nil, ErrInstall
		}
		return struct {
			Version, SQL, Snapshot, Runtime, Archive string
			Bindings                                 []reg.Binding
			References                               []reg.Reference
		}{"original-c1-and-raw-evidence-retained-backfill.v1", s.finite.metadata.revision, s.snapshotRevision, s.retained.receipt.pin.SHA256, s.external.archive.SnapshotRevision(), s.retained.Bindings(), refs}, nil
	}
	return nil, ErrInstall
}

// This method is private to the actual source-owning batch. Neither facts,
// Passed, observation hashes, revisions nor expiry are parameters.
func (b *issuedOriginalMixedAdoptionControls) signActualOriginalOwnerWitness(ctx context.Context, partition reg.Partition, kind string, key ed25519.PrivateKey) (a.SignedCoverageOwnerRecord, a.CoverageWitnessPin, error) {
	fail := func() (a.SignedCoverageOwnerRecord, a.CoverageWitnessPin, error) {
		return a.SignedCoverageOwnerRecord{}, a.CoverageWitnessPin{}, ErrInstall
	}
	if b == nil || b.origin != b || b.failed || b.coverage == nil || b.coverage.history == nil || b.coverage.history.finite == nil || !consumerSameContext(ctx, b.ctx) || !originalAdoptionSigningKey(key) || !b.coverage.history.local(ctx, false) || !time.Now().Before(b.until) {
		return fail()
	}
	valid := false
	for _, p := range originalAdoptionPartitions {
		if partition == p {
			valid = true
		}
	}
	if !valid {
		return fail()
	}
	observation, err := b.actualOwnerObservation(kind)
	if err != nil {
		return fail()
	}
	scope := struct {
		Database                                            reg.DatabaseIdentity
		Installation, Operation, Partition, Kind, SourceSet string
	}{b.snapshot.Database, b.snapshot.InstallationID, b.hold.set.owner.operation, string(partition), kind, b.coverage.history.snapshotRevision}
	facts := a.CoverageWitnessFacts{Database: b.snapshot.Database, InstallationID: b.snapshot.InstallationID, Partition: partition, Kind: kind, ScopeSHA256: originalObjectSHA(scope), ObservationSHA256: originalObjectSHA(observation), SnapshotRevision: b.coverage.history.snapshotRevision, FenceRevision: b.coverage.history.fenceRevision}
	source := b.controlSource(partition, kind)
	source.ContentSHA256 = originalObjectSHA(facts)
	record := a.CoverageWitnessRecord{Facts: facts, Source: source, Revision: b.recordRevision(), NotBefore: b.snapshot.ObservedAt, Until: b.until}
	raw, err := originalMixedIssuedJSON(record)
	if err != nil || len(raw) > 8192 {
		return fail()
	}
	signed := a.SignedCoverageOwnerRecord{Record: raw, Signature: ed25519.Sign(key, append([]byte(a.OriginalCoverageWitnessDomain), raw...))}
	pin := a.CoverageWitnessPin{CoverageOwnerPin: a.CoverageOwnerPin{Source: source, Issuer: append(ed25519.PublicKey(nil), key.Public().(ed25519.PublicKey)...)}, Partition: partition, Kind: kind, ScopeSHA256: facts.ScopeSHA256}
	return signed, pin, nil
}

// The fifth independent owner key attests exactly the sixteen issued source
// records. It cannot replace a missing witness or choose a replacement epoch.
func (b *issuedOriginalMixedAdoptionControls) signActualOriginalAdoption(ctx context.Context, key ed25519.PrivateKey) (a.SignedCoverageOwnerRecord, a.CoverageOwnerPin, error) {
	fail := func() (a.SignedCoverageOwnerRecord, a.CoverageOwnerPin, error) {
		return a.SignedCoverageOwnerRecord{}, a.CoverageOwnerPin{}, ErrInstall
	}
	if b == nil || b.origin != b || b.failed || b.coverage == nil || b.coverage.history == nil || b.coverage.history.finite == nil || !consumerSameContext(ctx, b.ctx) || !originalAdoptionSigningKey(key) || !b.coverage.history.local(ctx, false) || !originalAdoptionEmptyRegistry(b.prep, b.snapshot) || len(b.pins.Witnesses) != 16 || len(b.records) != 16 || !time.Now().Before(b.until) {
		return fail()
	}
	facts := a.CoverageAdoptionFacts{Database: b.snapshot.Database, InstallationID: b.snapshot.InstallationID, AdoptedEpoch: b.snapshot.Epoch + 1, Partitions: make([]a.CoveragePartitionAdoption, 0, 4)}
	for _, partition := range originalAdoptionPartitions {
		sources := map[string]reg.SourceRecord{}
		for _, pin := range b.pins.Witnesses {
			if pin.Partition == partition {
				if _, exists := sources[pin.Kind]; exists {
					return fail()
				}
				sources[pin.Kind] = pin.Source
			}
		}
		if len(sources) != 4 {
			return fail()
		}
		for _, kind := range originalAdoptionIssuerRoles[:4] {
			if sources[kind].RecordID == "" {
				return fail()
			}
		}
		owned := originalMixedPartitionReferences(b.coverage.refs, partition)
		facts.Partitions = append(facts.Partitions, a.CoveragePartitionAdoption{Partition: partition, SourceID: b.controlSource(partition, "partition").SourceID, SnapshotRevision: b.coverage.history.snapshotRevision, FenceRevision: b.coverage.history.fenceRevision, ReferenceCount: uint64(len(owned)), ReferencesSHA256: originalObjectSHA(owned), SQLCensus: sources["original_sql_census"], ImmutableExternalSnapshot: sources["immutable_external_snapshot"], WriterFence: sources["original_writer_fence"], HistoricalBackfill: sources["historical_backfill"]})
	}
	source := b.controlSource("", "adoption")
	source.ContentSHA256 = originalObjectSHA(facts)
	record := a.CoverageAdoptionRecord{Facts: facts, Source: source, Revision: b.recordRevision(), NotBefore: b.snapshot.ObservedAt, Until: b.until}
	raw, err := originalMixedIssuedJSON(record)
	if err != nil || len(raw) > 8192 {
		return fail()
	}
	return a.SignedCoverageOwnerRecord{Record: raw, Signature: ed25519.Sign(key, append([]byte(a.OriginalCoverageDomain), raw...))}, a.CoverageOwnerPin{Source: source, Issuer: append(ed25519.PublicKey(nil), key.Public().(ed25519.PublicKey)...)}, nil
}
